import {featurePrompt} from './guidance-ui.js';
import {gateDestination} from './wayfinding.js';
import {DISTRICTS,POINTS,POINT_BY_ID,GOODS,RESIDENT_NAMES,POWER_LABELS} from './district-data.js';
import {REGIONS,ITEMS,CROPS} from './data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,id,label,more='')=>`<button data-action="${action}" data-id="${esc(id)}" ${more}>${label}</button>`;
const item=id=>ITEMS[id]?.name||id;
const fmt=b=>Object.entries(b||{}).map(([id,n])=>item(id)+' ×'+n).join('、')||'无';
export const districtNeedsConfirm=q=>/^(battle|choice|cut|clear):|^(herbuproot|closeShop|dismantle)/.test(q.effect||'')||/挑战|超负荷|拆除|清伐|拔除|整株采收/.test(q.label||'');
const options=(list,selected)=>list.map(([id,name])=>`<option value="${id}" ${id===selected?'selected':''}>${esc(name)}</option>`).join('');
const empty=text=>`<div class="district-empty"><span aria-hidden="true">◇</span><p>${text}</p></div>`;
const names=Object.entries(DISTRICTS).map(([id,d])=>[id,d.name]);
function stateLabel(e,id){return !e.d.unlocked[id]?'◇ 待开通':e.s.visited[id]?'● 已到访':'○ 已开放';}
export function renderDistrictWorld(e,ui={}){const filter=ui.worldFilter||'all';return `<div class="district-world-head"><div><small>家园与远方 / 世界地图</small><h3>从家园，向外重建</h3><p>从熟悉的街巷寻找通路。带上补给，去接回人，也带回重建所需的物资。</p></div>${btn('dOpen','','地区事务','class="primary"')}</div><div class="district-filter" role="group" aria-label="地区筛选">${[['all','全部地区'],['open','已开放'],['new','尚未到访'],['herb','药草 / 医疗'],['parts','设备 / 零件']].map(([id,t])=>btn('dWorldFilter',id,t,`aria-pressed="${filter===id}"`)).join('')}</div><div class="district-world-grid">${Object.entries(DISTRICTS).filter(([id,d])=>filter==='all'||filter==='open'&&e.d.unlocked[id]||filter==='new'&&!e.s.visited[id]||d.goods.includes(filter)).map(([id,d])=>{const s=e.districtSummary(id),reason=e.districtUnlockReason(id);return `<article class="district-pair" style="--district:${d.color}"><div class="district-origin"><span>通路所在</span><b>${REGIONS[d.parent].name}</b>${btn('dDestination',d.parent,e.s.region===d.parent?'当前位置':'查看行程',e.s.region===d.parent?'disabled':'')}</div><div class="district-pair-line">↓ 修复通路</div><div class="district-new"><span class="district-mark">${d.mark}</span><div><small>${d.tag}</small><h3>${d.name}</h3></div><span class="district-state">${stateLabel(e,id)}</span></div><p>${d.purpose}</p><p class="district-operation">${e.d.jobs.filter(j=>j.region===id).length?e.d.jobs.filter(j=>j.region===id).length+'项工作正在进行':e.d.unlocked[id]?'通路畅通，可自由往返':'带上材料，修复通路'}</p><small>${e.d.unlocked[id]?d.risk:reason||'入口待修复 · '+fmt(d.cost)}</small><div class="button-row">${btn('dDestination',id,'查看行程')}${btn('dRegion',id,'地区手册')}</div></article>`;}).join('')}</div><div class="district-legend">◇ 待开通　○ 已开放　● 已到访　⚠ 出发前请留意危险</div>`;}
function materialRows(e,cost,region){return Object.entries(cost).map(([id,n])=>`<tr><td>${item(id)}</td><td>${e.districtQty(id,region)}</td><td>${e.d.reserves[region]?.[id]||0}</td><td class="${e.districtAvailable(id,region)<n?'district-error':''}">${e.districtAvailable(id,region)} / ${n}</td></tr>`).join('');}
function travelPanel(e,region){const d=DISTRICTS[region],r=REGIONS[region],reason=e.districtTravelReason(region),discount=(region==='courtyard'||e.s.region==='courtyard')&&e.flag('routes','roof')?8:0,minutes=Math.max(5,(e.projectDone('bridge')||e.spec('exploration','scout')?10:20)-discount);return `<div class="district-kicker">目的地行动卡</div><h2>${r.name}</h2><p>${d?.purpose||r.res}</p><dl class="district-facts"><div><dt>风险</dt><dd>${r.risk}</dd></div><div><dt>旅行投入</dt><dd>约${minutes}游戏分钟 · 体力5 · 饥饿2</dd></div><div><dt>可以获得</dt><dd>${d?d.goods.map(item).join('、')+'及本区设备服务':r.res}</dd></div><div><dt>返回路径</dt><dd>${d?'西侧入口返回'+REGIONS[d.parent].name:'地图选择返回农场'}</dd></div><div><dt>保留进度</dt><dd>修复、研究、居民故事永久保存。途中货物按游戏时间运输。</dd></div></dl>${reason?`<p class="district-reason">${esc(reason)}</p>`:''}<div class="button-row">${btn('dGo',region,'确认出发',`class="primary" ${reason||e.s.region===region?'disabled':''}`)}${d?btn('dView','entrance','查看入口条件'):''}</div>${d?`<div class="district-next">建议首站：${POINTS.find(p=>p.region===region).name}。进入地区后按E交互。</div>`:''}`;}
function entrancePanel(e,region){const d=DISTRICTS[region],reason=e.districtUnlockReason(region),near=e.s.region===d.parent&&Math.hypot(e.s.player.x-d.gate.x,e.s.player.y-d.gate.y)<115;return `<div class="district-kicker">通路修复</div><h2>${d.name}</h2><p>${d.purpose}</p><div class="district-result"><b>${e.d.unlocked[region]?'入口已开放':'修复后可通行、使用当地仓库并恢复地区设施'}</b><p>入口位于${REGIONS[d.parent].name}。先追踪入口，再带材料靠近。</p></div><table class="district-table"><thead><tr><th>材料</th><th>拥有</th><th>预留</th><th>可用/需要</th></tr></thead><tbody>${materialRows(e,d.cost,d.parent)}</tbody></table>${reason?`<p class="district-reason">先${reason}</p>`:''}<div class="button-row">${btn('dTrackGate',region,'追踪入口')}${btn('dUnlock',region,e.d.unlocked[region]?'已开放':'修复通路',`class="primary" ${e.d.unlocked[region]||reason||!near?'disabled':''}`)}${btn('dDestination',region,'查看行程')}</div><p class="district-caption">在入口现场使用随身材料；农场入口可使用家园仓库。</p>`;}
function pointPanel(e,id,ui){const def=POINT_BY_ID[id],p=e.point(id),region=def.region,opts=e.districtOptions(id);const needUI=['cargo','dispatch'].includes(id);return `<div class="district-kicker">${DISTRICTS[region].name} / ${DISTRICTS[region].tag}</div><h2>${def.name}</h2><p>${def.desc}</p><div class="district-result"><b>带来的改变</b><p>${def.purpose}</p></div><div class="district-action-meta"><span>${e.s.region===region?'在本区域':'需要前往'+DISTRICTS[region].name}</span>${btn('dTrack',id,'设为主目标')}${btn('dOptional',id,e.d.optional.includes(id)?'取消可选行动':'列为可选行动')}</div>${id==='rotation'||id==='intercrop'?`<div class="district-caption">上层8格 / 下层${e.d.plots.filter(p=>p.bed===1&&!p.buffer).length}格。批量播种显示所需种子；也可走到田格旁按E操作。已成熟 ${e.d.plots.filter(p=>p.crop&&p.growth>=CROPS[p.crop].grow).length} 株。</div>`:''}${id==='restore'&&p.flags.inspected===e.s.day?`<p class="district-note">${e.s.day%2?'外壳破损：用废金属2修复，售价28。':'轴承磨损：用零件1修复，售价38。'}</p>`:''}${['sterile','modules','power','load'].includes(id)?powerPanel(e,region):''}<div class="district-actions">${opts.map(opt=>{const q=e.districtQuote(id,opt.id),done=q.done;return `<article class="district-action"><div><b>${opt.label}</b><p>投入：${fmt(q.cost)}${q.fee?' · '+q.fee+'金':''}</p><small>${q.minutes?'耗时 '+q.minutes+' 游戏分钟 · ':''}${Object.keys(q.out||{}).length?'产出 '+fmt(q.out)+' → 本地仓库':q.money?'收入 '+q.money+'金':'结果：'+def.purpose}</small>${q.reason?`<span class="district-reason ${done?'done':''}">${esc(q.reason)}</span>`:''}</div><div class="district-action-buttons">${btn(districtNeedsConfirm(q)?'dPreview':'dQuick',id+':'+opt.id,done?'已完成':districtNeedsConfirm(q)?'查看风险并确认':opt.label,q.reason?'disabled':'')}${q.repeat&&q.minutes?btn('dPreview',id+':'+opt.id,'批量安排',done?'disabled':''):''}</div></article>`;}).join('')}</div>${id==='cargo'?freightForm(e):id==='dispatch'?routeForm(e):''}${['streetdefense','drill','overload'].includes(id)?battlePanel(e):''}${id==='evidence'?`<details><summary>查看调查记录与推理提示</summary><p>${e.flag('evidence','log')?'日志记载：雨后井水变浑。':'日志：先穿越回廊取得档案，并在此整理。'}</p><p>${e.flag('evidence','pipe')?'管线图显示：旧排水管与温室旁路相接。':'管线图：尚未完成测绘。'}</p><p>${e.flag('experiment','water')?'水质对照：未过滤水样出现沉淀，空气样本无对应变化。':'水质对照：需要药草与溪谷野生样本。'}</p></details>`:''}${needUI?'':'<p class="district-caption">操作前会再次检查距离、材料、预留量与条件。菜单内世界暂停。</p>'}`;}
function previewPanel(e,ui){const [id,key]=ui.preview.split(':'),q=e.districtQuote(id,key,ui.batch||1),def=POINT_BY_ID[id];if(!def||!q.cost)return empty('操作已变化，请返回项目重新选择。');return `<div class="district-kicker">操作预览 / ${def.name}</div><h2>${q.label}</h2>${q.repeat&&q.minutes&&Object.keys(q.out).length?`<label class="district-field">批次数<select id="d-batch">${options([1,2,3,5,10].map(n=>[String(n),String(n)+'批']),String(q.n))}</select></label>`:''}<table class="district-table"><thead><tr><th>材料</th><th>拥有</th><th>预留</th><th>可用/需要</th></tr></thead><tbody>${materialRows(e,q.cost,q.region)||'<tr><td colspan="4">不消耗物品</td></tr>'}</tbody></table><dl class="district-facts"><div><dt>金币</dt><dd>现在${e.s.money} → 操作后${e.s.money-q.fee}${q.money?'；完成后另获'+q.money:''}</dd></div><div><dt>耗时</dt><dd>${q.minutes?Math.ceil(q.minutes)+'游戏分钟，离开菜单后推进':'立即生效'}</dd></div><div><dt>产出与去向</dt><dd>${Object.keys(q.out).length?fmt(q.out)+' → '+DISTRICTS[q.region].name+'仓库':def.purpose}</dd></div></dl>${q.reason?`<p class="district-error">${esc(q.reason)}</p>`:''}<div class="button-row">${btn('dExecute',ui.preview,'确认投入',`class="primary" ${q.reason?'disabled':''}`)}${btn('dPoint',id,'返回项目')}${q.reason?btn('dTrack',id,'追踪现场'):''}</div>`;}
function powerPanel(e,region){if(!['quarantine','railDepot'].includes(region))return '';const used=e.d.power[region],max=region==='quarantine'?(e.flag('power','upgrade')?2:1):(e.flag('load','upgrade')?3:2);return `<div class="district-power"><b>供电 ${used.length}/${max} 路</b><span>${used.map(k=>'● '+POWER_LABELS[k]).join('　')||'所有设备已断电'}</span><small>未接通的设备暂停加工，已投入材料和进度保留。</small>${btn('dPoint',region==='quarantine'?'power':'load','调整供电')}</div>`;}
function storagePanel(e,region){const store=e.districtStore(region)||{},local=e.s.region===region,keys=[...new Set([...Object.keys(store),...Object.keys(e.s.inventory)])].filter(id=>(store[id]||0)>0||(e.s.inventory[id]||0)>0);return `<div class="district-kicker">物资位置 / ${REGIONS[region].name}</div><h2>仓储与预留</h2><p>背包随身携带，本地仓库只在当前地区可用。在途货物抵达前不能再次使用。</p>${!local?'<p class="district-reason">正在远程查看，前往本区域后才能存取。</p>':''}<div class="district-table-wrap"><table class="district-table"><thead><tr><th>物品</th><th>背包</th><th>当地仓库</th><th>预留</th><th>转移一组</th></tr></thead><tbody>${keys.map(id=>`<tr><td>${item(id)}</td><td>${e.s.inventory[id]||0}</td><td>${store[id]||0}</td><td>${e.d.reserves[region]?.[id]||0}</td><td><div class="district-inline">${btn('dDeposit',id,'存入',!local||!(e.s.inventory[id]>0)||ITEMS[id].type==='tool'||ITEMS[id].type==='weapon'?'disabled':'')}${btn('dWithdraw',id,'取出',!local||!(store[id]>0)?'disabled':'')}</div></td></tr>`).join('')}</tbody></table></div><h3>为工程和餐食保留材料</h3><div class="district-form"><label>物品<select id="d-reserve-item">${options(GOODS.map(id=>[id,item(id)]),'bread')}</select></label><label>保留数量<input id="d-reserve-count" type="number" min="0" max="99" value="2"></label>${btn('dReserve','','保存预留',!local?'disabled':'')}</div><p class="district-caption">预留量会从本区手动操作、居民售货与运输可用量中扣除。需要使用时可将预留改为0。</p><div class="button-row">${btn('dRest','','在休整点休息1小时',!local?'disabled':'')}${btn('dView','freight','查看运输')}</div>${local?'<p class="district-caption">休整需要靠近地区仓库，附近无敌人；补满水壶、恢复体力，消耗5饥饿。</p>':''}`;}
function jobsPanel(e){return `<div class="district-kicker">跨区生产 / 时间与产能</div><h2>生产看板</h2><p>已投料工作可以暂停或取消；完成品自动进入所属地区仓库。</p>${e.d.jobs.length?e.d.jobs.map(j=>{const reason=e.districtJobReason(j);return `<article class="district-job"><div><small>${REGIONS[j.region].name} / ${reason||'正在进行'}</small><h3>${j.label}</h3><p>剩余${Math.ceil(j.remaining)}分钟 · 成品${fmt(j.out)}${j.money?' · '+j.money+'金':''}</p><progress max="${j.total}" value="${j.total-j.remaining}"></progress></div><div class="district-inline">${btn('dJobUp',j.id,'提前')}${btn('dJob',j.id,j.paused?'继续':'暂停')}${btn('dCancelJob',j.id,'取消并查看返料')}</div></article>`;}).join(''):empty('暂无地区工作。到商街、科研园或货运站投入第一批材料。')}${e.c.production.length?`<h3>农场加工 ${e.c.production.length} 项</h3><p>${e.c.production.map(j=>item(Object.keys(j.out)[0])+' · '+(j.ready?'待领取':Math.ceil(j.remaining)+'分钟')).join('；')}</p>${btn('dHomeProduction','','查看农场加工')}`:''}`;}
function freightForm(e){const regions=[['farm','余烬农场'],...names].filter(([id])=>id==='farm'||e.d.unlocked[id]);return `<h3>办理单次托运</h3><p>货物从当前地区仓库扣除。每5件占一格，金属类每件重量2，其他重量1。</p><div class="district-form"><label>目的地<select id="d-freight-to">${options(regions.filter(([id])=>id!==e.s.region),'farm')}</select></label><label>货物<select id="d-freight-item">${options(GOODS.map(id=>[id,item(id)]),'parts')}</select></label><label>数量<input id="d-freight-count" type="number" min="1" max="30" value="3"></label><label>班次<select id="d-freight-speed"><option value="normal">普通 · 6金 / 180分</option><option value="fast">急件 · 12金 / 90分</option></select></label>${btn('dFreightPreview','','查看装载与费用')}</div>`;}
function freightPanel(e,ui){return `<div class="district-kicker">物流 / 货物在哪里</div><h2>货运与班次</h2><div class="district-metrics"><div><b>${e.d.freight.length}/4</b><span>在途班次</span></div><div><b>${e.flag('cargo','upgrade')?6:4}格</b><span>单车货位</span></div><div><b>${e.flag('cargo','upgrade')?30:20}</b><span>单车重量</span></div></div>${e.d.freight.length?e.d.freight.map(f=>`<article class="district-job"><div><b>${REGIONS[f.from].name} → ${REGIONS[f.to].name}</b><p>${fmt(f.items)} · 剩余${Math.ceil(f.remaining)}分钟</p><progress max="${f.total}" value="${f.total-f.remaining}"></progress></div><span>已扣货 · 运输中</span></article>`).join(''):empty('暂无在途货物。到货运站办理托运，将物资送到需要的地方。')}${freightForm(e)}${routeForm(e)}`;}
function routeForm(e){return `<h3>自动班次 · ${e.d.routes.length}/${e.flag('dispatch','upgrade')?3:1}</h3>${e.d.routes.map(r=>`<article class="district-job"><div><b>${REGIONS[r.from].name} → ${REGIONS[r.to].name}</b><p>${item(r.item)}×${r.n}，留${r.reserve} · ${r.enabled?esc(r.status):'已暂停'}</p></div><div class="district-inline">${btn('dRouteToggle',r.id,r.enabled?'暂停':'启用')}${btn('dRouteRemove',r.id,'移除')}</div></article>`).join('')}<p class="district-caption">每6游戏小时尝试一班，运费6金＋货运站废金属1维护。缺货、保留量不足或班次已满时暂停发车。</p>${e.s.region==='railDepot'&&e.flag('dispatch','built')?`<div class="district-form"><label>起点<select id="d-route-from">${options([['farm','余烬农场'],...names],'valley')}</select></label><label>终点<select id="d-route-to">${options([['farm','余烬农场'],...names],'quarantine')}</select></label><label>货物<select id="d-route-item">${options(GOODS.map(id=>[id,item(id)]),'herb')}</select></label><label>每班数量<input id="d-route-count" type="number" min="1" max="10" value="3"></label><label>至少留存<input id="d-route-reserve" type="number" min="0" max="99" value="2"></label>${btn('dRouteAdd','','增加班次')}</div>`:`<p class="district-reason">在货运站修复调度台后，可以新增自动班次。</p>${btn('dPoint','dispatch','查看调度台')}`}`;}
function workersPanel(e){return `<div class="district-kicker">居民协作 / 一个居民一个岗位</div><h2>外派排班</h2><p>外派会暂停原有岗位。工作需要床位、工作餐，疲劳低于85，并在白天进行。</p>${e.c.residents.length?e.c.residents.map(r=>`<article class="district-worker"><div><h3>${RESIDENT_NAMES[r.id]}</h3><p>${e.d.workers[r.id]?'当前外派：'+REGIONS[e.d.workers[r.id]].name:'当前在农场：'+e.residentWorkReason(r)}</p><small>疲劳${Math.round(r.fatigue)} · ${r.fed?'已供餐':'等待工作餐'} · 离岗后原农务、治疗或维修暂停</small></div><div class="button-row">${[['valley','溪谷农务'],['stationMarket','商街驻店'],['quarantine','科研园护理']].filter(([id])=>id==='stationMarket'||id==='valley'&&r.id==='farmer'||id==='quarantine'&&r.id==='medic').map(([id,t])=>btn('dWorker',r.id+':'+id,t,!e.d.unlocked[id]?'disabled':'')).join('')}${btn('dWorker',r.id+':home','召回农场')}</div></article>`).join(''):empty('先到住宅区、医院或仓库寻找需要帮助的幸存者。')}${btn('dResidents','','查看床位与工作餐')}`;}
function ledgerPanel(e,region){const entries=e.d.ledger.filter(l=>l.region===region),today=entries.filter(l=>l.day===e.s.day),net={};for(const l of today)for(const [id,n]of Object.entries(l.delta))net[id]=(net[id]||0)+n;return `<div class="district-kicker">实际记录 / 第${e.s.day}天</div><h2>地区收支与成果</h2><p>下面是已发生的投入、产出与运送。生产计划不计入实际收入；手动存取不计作新产出。</p><div class="district-metrics"><div><b>${today.reduce((n,l)=>n+l.money,0)}</b><span>今日净金币</span></div><div><b>${e.d.jobs.filter(j=>j.region===region).length}</b><span>在制工作</span></div></div><p class="district-note">今日已记录物资净变化：${Object.entries(net).map(([id,n])=>item(id)+(n>=0?' +':' ')+n).join('、')||'暂无'}</p>${entries.length?`<ol class="district-timeline">${entries.slice(0,25).map(l=>`<li><small>第${l.day}天 ${String(Math.floor(l.minute/60)).padStart(2,'0')}:${String(l.minute%60).padStart(2,'0')}</small><b>${esc(l.text)}</b>${Object.keys(l.delta).length?`<span>${Object.entries(l.delta).map(([id,n])=>item(id)+(n>0?' +':' ')+n).join('、')}</span>`:''}</li>`).join('')}</ol>`:empty('尚未产生记录。完成第一次行动后，投入与结果会显示在这里。')}`;}
function needsPanel(e){const choices=[['medkit','药包','herb','cloth','sterile'],['cloth','布料','cotton',null,'modules'],['bread','工作餐','radish',null,'shops'],['parts','零件','scrap',null,'diagnose']];return `<div class="district-kicker">材料需求 / 获取 → 使用 → 下一步</div><h2>这件物品有什么用</h2>${choices.map(([id,name,a,b,point])=>`<article class="district-need"><h3>${name}</h3><p>${e.itemPurpose(id)}</p><div class="district-chain"><span>${item(a)}${b?' ＋ '+item(b):''}</span><span>→</span><span>${name}</span></div><p>背包${e.qty(id)} · 家园${e.s.storage[id]||0} · 五区${Object.values(e.d.stores).reduce((n,s)=>n+(s[id]||0),0)} · 在途${e.d.freight.reduce((n,f)=>n+(f.items[id]||0),0)}</p>${btn('dPoint',point,'查看相关设施')}${btn('dWorldResource',a,'地图查找'+item(a))}</article>`).join('')}<p class="district-caption">工作餐在农场加工。商街提供销售用途；零件可在旧地图搜索、易货或机床生产。</p>`;}
function battlePanel(e){const b=e.d.battle||e.d.lastBattle;if(!b)return '<p class="district-note">挑战自愿开启；先准备料理与药品。家园尸潮和地区挑战不会同时启动。</p>';return `<div class="district-report"><h3>${POINT_BY_ID[b.id].name} · ${e.d.battle?'进行中':b.won?'胜利':'已结束'}</h3><p>击败 ${b.kills}/${b.count} · 射点命中 ${b.towerHits} · 陷阱命中 ${b.trapHits} · 受到伤害 ${Math.round(b.damage)}</p>${e.d.battle?`<p>剩余 ${Math.ceil(b.remaining)}秒；关闭菜单继续战斗。</p>`:''}<p>建设、研究与已完成故事保留，弹药和药品按实际使用消耗。</p></div>`;}
function retreatPanel(e){return `<div class="district-kicker">撤退 / 恢复</div><h2>带着进度回来</h2><p>主动撤退不丢物资，不退还已用弹药和药品。正在加工的物品和货运继续按游戏时间推进。</p>${e.d.battle?'<p class="district-reason">撤退会结束当前挑战，稍后可以重新发起；设施与调查不重置。</p>':''}<p>如果倒下：部分外出普通物资留在原地，金币损失5%。地图标出遗落背包。</p>${battlePanel(e)}<div class="button-row">${btn('dRetreat','','撤回入口外','class="primary"')}${btn('dDestination','farm','查看返回家园行程')}</div>`;}
export function renderDistricts(e,ui={}){ui.region=REGIONS[ui.region]?ui.region:DISTRICTS[e.s.region]?e.s.region:e.d.focus;const region=ui.region,def=DISTRICTS[region]||DISTRICTS.valley;const active=ui.point&&POINT_BY_ID[ui.point]?ui.point:POINTS.find(p=>p.region===(DISTRICTS[region]?region:'valley')).id;const view=ui.view||'point';let body='';if(ui.confirm){body=`<div class="district-kicker">请确认</div><h2>${esc(ui.confirm.title)}</h2><p>${esc(ui.confirm.text)}</p><div class="button-row">${btn(ui.confirm.action,ui.confirm.id,'确认','class="primary"')}${btn('dDismiss','','取消')}</div>`;}else if(ui.preview)body=previewPanel(e,ui);else if(view==='travel')body=travelPanel(e,region);else if(view==='entrance')body=entrancePanel(e,DISTRICTS[region]?region:'valley');else if(view==='storage')body=storagePanel(e,region);else if(view==='jobs')body=jobsPanel(e);else if(view==='freight')body=freightPanel(e,ui);else if(view==='workers')body=workersPanel(e);else if(view==='ledger')body=ledgerPanel(e,DISTRICTS[region]?region:'valley');else if(view==='needs')body=needsPanel(e);else if(view==='retreat')body=retreatPanel(e);else body=pointPanel(e,active,ui);
 if(ui.simple!==false&&view==='point')return `<div class="simple-site"><header class="simple-site-header"><small>${def.name} · 现场工作</small>${btn('gJournal','','返回当前任务')}</header>${featurePrompt(e,'d:'+active)}${body}<details class="simple-site-other"><summary>这里还有什么</summary><div>${POINTS.filter(p=>p.region===POINT_BY_ID[active].region&&p.id!==active).map(p=>btn('dPoint',p.id,p.name)).join('')}${btn('dView','jobs','正在进行的工作')}${btn('dView','storage','当地仓库')}${btn('dAdvanced','','地区事务')}</div></details></div>`;
 return `<div class="district-workspace ${ui.detail?'district-detail-open':''}" style="--district:${def.color}"><nav class="district-nav" aria-label="五区导航"><div class="district-nav-title">地区事务</div>${names.map(([id,name])=>btn('dRegion',id,`<span>${DISTRICTS[id].mark}</span>${name}`,`aria-current="${id===region?'page':'false'}"`)).join('')}<div class="district-nav-caption">跨区管理</div>${[['storage','仓储与预留'],['jobs','生产看板'],['freight','货运与班次'],['workers','居民排班'],['needs','物品用途'],['ledger','收支与成果']].map(([id,t])=>btn('dView',id,t,`aria-pressed="${view===id}"`)).join('')}<div class="district-nav-bottom">${btn('dWorld','','世界地图')}${btn('dHome','','营地手册')}</div></nav><aside class="district-list" aria-label="地区设施列表"><div class="district-list-title"><small>${def.tag}</small><h3>${def.name}</h3><p>${stateLabel(e,DISTRICTS[region]?region:'valley')}</p></div>${btn('dView','entrance','入口与开放条件')}${btn('dHideDone','',ui.hideDone?'显示所有设施':'只看尚未使用')}${POINTS.filter(p=>p.region===(DISTRICTS[region]?region:'valley')&&(!ui.hideDone||e.point(p.id).count===0)).map(p=>{const busy=e.d.jobs.some(j=>j.point===p.id),done=e.point(p.id).count>0;return btn('dPoint',p.id,`<span><b>${p.name}</b><small>${busy?'◷ 工作进行中':done?'● 已使用 · 可继续经营':'○ 尚待探索'}</small></span>`,`class="district-list-row ${active===p.id&&view==='point'?'selected':''}"`);}).join('')}</aside><section class="district-detail" aria-label="当前项目"><div class="district-detail-top">${btn('dBack','','‹ 返回地区列表','class="district-mobile-back"')}<small>世界已暂停</small>${btn('dView','retreat','撤退与恢复',!DISTRICTS[e.s.region]?'disabled':'')}</div><div class="district-scroll">${body}${e.d.optional.length?'<div class="district-next"><b>可选行动</b><div class="button-row">'+e.d.optional.map(id=>btn('dPoint',id,POINT_BY_ID[id].name)).join('')+'</div></div>':''}</div></section></div>`;
}
export function handleDistrictAction(action,button,ctx){if(!action?.startsWith('d'))return false;const {engine:e,ui,root,showMenu,closeMenu,renderMenu,save,toast}=ctx,id=button.dataset.id||'',val=(key,fallback='')=>root.querySelector('#'+key)?.value??fallback;const open=(args={})=>{ui.preview=null;ui.confirm=null;Object.assign(ui,args);showMenu('districts');};
 if(action==='dOpen')open({region:POINT_BY_ID[e.d.track]?.region||(DISTRICTS[e.s.region]?e.s.region:e.d.focus),point:e.d.track,view:e.d.unlocked[POINT_BY_ID[e.d.track]?.region||(DISTRICTS[e.s.region]?e.s.region:e.d.focus)]?'point':'entrance',detail:true});
 else if(action==='dRegion')open({region:id,point:POINTS.find(p=>p.region===id)?.id,view:e.d.unlocked[id]?'point':'entrance',detail:!e.d.unlocked[id]});
 else if(action==='dEntrance')open({region:id,view:'entrance',detail:true});
 else if(action==='dPoint')open({region:POINT_BY_ID[id].region,point:id,view:'point',detail:true,simple:true});
 else if(action==='dView')open({view:id,detail:true,region:id==='storage'?(DISTRICTS[e.s.region]?e.s.region:ui.region):ui.region});
 else if(action==='dDestination')showMenu('map',{selected:id});
 else if(action==='dGo'){if(e.travel(id)){closeMenu();save();}return true;}
 else if(action==='dUnlock'){e.unlockDistrict(id);renderMenu();save();}
 else if(action==='dTrack'||action==='dTrackGate'){const target=action==='dTrack'?{...POINT_BY_ID[id],label:POINT_BY_ID[id].name}:gateDestination(e,id);if(e.guidance){e.guidance.target=target;e.guidance.focus=action==='dTrack'?'d:'+id:'gate:'+id;e.d.track=null;}else e.d.track=action==='dTrack'?id:null;ctx.rebuildUI.target=target;e.r.focus=null;if(e.s.region===target?.region)closeMenu();else showMenu('map',{selected:target?.region});toast('已标记：'+target?.label+' · M查看路线');save();}
 else if(action==='dAdvanced'){ui.simple=false;renderMenu();}
 else if(action==='dQuick'){const [p,key]=id.split(':'),q=e.districtQuote(p,key);if(districtNeedsConfirm(q)){ui.preview=id;ui.batch=1;}else e.districtAct(p,key,1);renderMenu();save();}
 else if(action==='dPreview'){ui.preview=id;ui.batch=1;ui.detail=true;renderMenu();}
 else if(action==='dExecute'){const [p,key]=id.split(':');e.districtAct(p,key,ui.batch||1);ui.preview=null;renderMenu();save();}
 else if(action==='dBack'){ui.detail=false;ui.preview=null;ui.confirm=null;renderMenu();}
 else if(action==='dWorld'){showMenu('map');}
 else if(action==='dWorldFilter'){ui.worldFilter=id;renderMenu();}
 else if(action==='dWorldResource'){const target=Object.entries(DISTRICTS).find(([,d])=>d.goods.includes(id));showMenu('map',{selected:target?.[0]||'market'});}
 else if(action==='dHome'){showMenu('rebuild',{tab:'overview'});}
 else if(action==='dHomeProduction'){showMenu('camp',{tab:'production'});}
 else if(action==='dResidents'){showMenu('rebuild',{tab:'residents'});}
 else if(action==='dDeposit'||action==='dWithdraw'){const amount=action==='dDeposit'?(e.s.inventory[id]||0):(e.districtStore()?.[id]||0);e.districtTransfer(id,amount,action==='dDeposit');renderMenu();save();}
 else if(action==='dReserve'){e.setDistrictReserve(val('d-reserve-item'),Number(val('d-reserve-count')));renderMenu();save();}
 else if(action==='dRest'){e.districtRest();renderMenu();save();}
 else if(action==='dOptional'){e.toggleOptionalPoint(id);renderMenu();save();}
 else if(action==='dHideDone'){ui.hideDone=!ui.hideDone;renderMenu();}
 else if(action==='dJobUp'){e.reorderDistrictJob(id);renderMenu();save();}
 else if(action==='dJob'){e.toggleDistrictJob(id);renderMenu();save();}
 else if(action==='dCancelJob'){const j=e.d.jobs.find(j=>j.id===id);if(j){const refund=Object.fromEntries(Object.entries(j.cost).map(([k,n])=>[k,Math.floor(n*j.remaining/j.total)]));ui.confirm={title:'取消'+j.label,text:'未加工比例返还：'+fmt(refund)+'。不会产生完成品。',action:'dCancelJobConfirm',id};renderMenu();}}
 else if(action==='dCancelJobConfirm'){e.cancelDistrictJob(id);ui.confirm=null;renderMenu();save();}
 else if(action==='dDismiss'){ui.confirm=null;renderMenu();}
 else if(action==='dWorker'){const [person,region]=id.split(':');e.assignDistrictWorker(person,region==='home'?null:region);renderMenu();save();}
 else if(action==='dFreightPreview'){const to=val('d-freight-to'),item=val('d-freight-item'),n=Number(val('d-freight-count')),fast=val('d-freight-speed')==='fast',q=e.freightQuote(e.s.region,to,item,n,fast);if(q.reason)toast(q.reason,'warn');else{ui.freight={from:e.s.region,to,item,n,fast};ui.confirm={title:'确认运输：'+fmt(q.items),text:q.slots+'格 / 重量'+q.weight+' · 运费'+q.fee+'金 · '+Math.ceil(q.minutes)+'游戏分钟后到'+REGIONS[to].name+'仓库。发出即扣货。',action:'dFreightSend',id:''};renderMenu();}}
 else if(action==='dFreightSend'){const f=ui.freight;if(f)e.sendDistrictFreight(f.from,f.to,f.item,f.n,f.fast);ui.confirm=null;ui.freight=null;renderMenu();save();}
 else if(action==='dRouteAdd'){e.setDistrictRoute(val('d-route-from'),val('d-route-to'),val('d-route-item'),Number(val('d-route-count')),Number(val('d-route-reserve')));renderMenu();save();}
 else if(action==='dRouteToggle'||action==='dRouteRemove'){e.manageDistrictRoute(id,action==='dRouteRemove');renderMenu();save();}
 else if(action==='dRetreat'){if(e.retreatDistrict()){closeMenu();save();}}
 else return false;return true;
}
